_CORE_SRC = '# Action format: "[(from_node, to_node, count), ...]"\n# "revenue_p = sum of node_value[i] over all nodes i that player p owns"\n# "upkeep_p = UPKEEP * (UNITS_PER_PLAYER - units of p on its own base)"\n# "profit_p = revenue_p - upkeep_p"\n# Ownership, not capacity sharing, determines revenue in this game. Capturing an\n# opponent-owned node therefore changes the revenue margin by twice its value.\n\nimport time\n\nTIME_BUDGET = 0.25\nN_TURNS = 80\nUNITS_PER_PLAYER = 20\nUPKEEP = 2.0\n\n\ndef payout(values, owned, units_at_base):\n    """The specification\'s exact single-turn payout."""\n    revenue = sum(v for v, owner in zip(values, owned) if owner)\n    upkeep = UPKEEP * (UNITS_PER_PLAYER - units_at_base)\n    return float(revenue - upkeep)\n\n\ndef preprocess_map(n, edges):\n    adjacency = [[] for _ in range(n)]\n    lengths = {}\n    distance = [[100000] * n for _ in range(n)]\n    for i in range(n):\n        distance[i][i] = 0\n    for u, v, length in edges:\n        adjacency[u].append(v)\n        adjacency[v].append(u)\n        lengths[u, v] = lengths[v, u] = length\n        distance[u][v] = distance[v][u] = length\n    for neighbors in adjacency:\n        neighbors.sort()\n    for k in range(n):\n        for i in range(n):\n            for j in range(n):\n                alternative = distance[i][k] + distance[k][j]\n                if alternative < distance[i][j]:\n                    distance[i][j] = alternative\n    hops = [[-1] * n for _ in range(n)]\n    for i in range(n):\n        for j in range(n):\n            if i != j:\n                for v in adjacency[i]:\n                    if lengths[i, v] + distance[v][j] == distance[i][j]:\n                        hops[i][j] = v\n                        break\n    return adjacency, lengths, distance, hops\n\n\ndef legal_action(proposals, start_units, lengths, n):\n    """Only original, start-of-turn units can pay for each aggregated move."""\n    available = list(start_units)\n    result = []\n    for (source, destination), count in sorted(proposals.items()):\n        if not (0 <= source < n and 0 <= destination < n):\n            continue\n        if (source, destination) not in lengths:\n            continue\n        count = min(int(count), available[source])\n        if count > 0:\n            result.append((int(source), int(destination), int(count)))\n            available[source] -= count\n    return result\n\n\nclass Strategy:\n    def __init__(self, player_id):\n        self.player_id = player_id\n        self.map_data = None\n        self.tokens = []\n        self.previous_turn = None\n        self.previous_enemy = None\n        self.mobility = 0.25\n        self.bad_reports = 0\n        self.conservative = False\n\n    def _synchronize_tokens(self, obs):\n        # A token stores destination/current node, first movable turn, and goal.\n        # Token identities are internal only; observations are always authoritative.\n        t = obs["turn"]\n        n = obs["n_nodes"]\n        observed_nodes = list(obs["player_units"])\n        observed_transits = {}\n        for u, v, count, arrival in obs.get("player_transits", []):\n            key = (v, arrival)\n            observed_transits[key] = observed_transits.get(key, 0) + count\n        nodes = [0] * n\n        transits = {}\n        for node, ready, goal in self.tokens:\n            if ready <= t:\n                nodes[node] += 1\n            else:\n                key = (node, ready)\n                transits[key] = transits.get(key, 0) + 1\n        if nodes != observed_nodes or transits != observed_transits:\n            self.tokens = []\n            for node, count in enumerate(observed_nodes):\n                self.tokens.extend([[node, t, node] for _ in range(count)])\n            for u, v, count, arrival in obs.get("player_transits", []):\n                self.tokens.extend([[v, arrival, v] for _ in range(count)])\n\n    def _opponent_prediction(self, obs):\n        t = obs["turn"]\n        enemy = list(obs["opponent_units"])\n        if self.previous_enemy is not None and self.previous_turn == t - 1:\n            moved = sum(max(0, a - b)\n                        for a, b in zip(self.previous_enemy, enemy))\n            activity = min(1.0, moved / 3.0)\n            self.mobility = 0.8 * self.mobility + 0.2 * activity\n        predictions = [float(x) for x in enemy]\n        for u, v, count, arrival in obs.get("opponent_transits", []):\n            predictions[v] += count\n\n        # Blend visible stay-put forces with a small, reachable greedy scout\n        # prediction. Never pretend the opponent\'s entire base army teleports.\n        base = obs["opponent_base"]\n        _, _, distances, _ = self.map_data\n        candidates = []\n        for v, value in enumerate(obs["node_value"]):\n            if value and not obs["opponent_owned"][v] and predictions[v] == 0:\n                attractiveness = value / (distances[base][v] + 2.0)\n                candidates.append((-attractiveness, v))\n        spare = enemy[base]\n        for _, v in sorted(candidates)[:min(spare, 3)]:\n            predictions[v] += 0.25 + 0.55 * self.mobility\n        self.previous_enemy = enemy\n        return predictions\n\n    def _plan(self, obs, prediction, deadline):\n        t = obs["turn"]\n        remaining = N_TURNS - t\n        base = obs["player_base"]\n        values = obs["node_value"]\n        owned = obs["player_owned"]\n        theirs = obs["opponent_owned"]\n        leads = obs["player_lead_turns"]\n        _, _, distance, _ = self.map_data\n        tokens = self.tokens\n        free = set(range(len(tokens)))\n        goals = [base] * len(tokens)\n        candidates = [v for v, value in enumerate(values) if value > 0]\n\n        # Greedy bundle allocation: strict-majority captures have a threshold,\n        # so bidding one unit at a time would miss profitable contested captures.\n        # A complete minimum winning bundle is the relevant marginal investment.\n        while free and candidates and time.perf_counter() < deadline:\n            best = None\n            for target in candidates:\n                if time.perf_counter() >= deadline:\n                    break\n                enemy_count = int(prediction[target] + 0.35)\n                defending = bool(owned[target])\n                needed = enemy_count if defending else enemy_count + 1\n                if needed == 0 or needed > len(free):\n                    continue\n                ranked = []\n                for index in sorted(free):\n                    node, ready, old_goal = tokens[index]\n                    delay = max(0, ready - t) + distance[node][target]\n                    # Keep established expeditions intact when alternatives tie.\n                    sticky = 0.15 if old_goal == target else 0.0\n                    ranked.append((delay - sticky, delay, index))\n                ranked.sort()\n                group = ranked[:needed]\n                arrival_delay = max(entry[1] for entry in group)\n                if defending:\n                    capture_delay = arrival_delay\n                else:\n                    capture_delay = arrival_delay + 1\n                    if arrival_delay == 0 and leads[target] >= 1:\n                        capture_delay = 0\n                earning_turns = max(0, remaining - capture_delay)\n                if earning_turns <= 0:\n                    continue\n\n                # Defending prevents the opponent earning AND us losing revenue.\n                multiplier = 2.0 if defending or theirs[target] else 1.0\n                reward = multiplier * values[target] * earning_turns\n                travel_cost = 0.0\n                for _, delay, index in group:\n                    node, ready, old_goal = tokens[index]\n                    # A returning unit would itself incur upkeep until reaching\n                    # home: count only the additional cost of this assignment.\n                    return_delay = max(0, ready - t) + distance[node][base]\n                    baseline = min(remaining, max(0, return_delay - 1))\n                    expedition = min(remaining, delay + (0 if defending else 1))\n                    travel_cost += UPKEEP * (expedition - baseline)\n\n                # Match a stationary enemy after capture; the extra capturing\n                # unit can return. Uncontested ownership needs no garrison.\n                holding = enemy_count\n                holding_cost = UPKEEP * holding * earning_turns\n                extra = 0 if defending else 1\n                return_cost = UPKEEP * extra * min(\n                    earning_turns, max(0, distance[target][base] - 1)\n                )\n                profit = reward - travel_cost - holding_cost - return_cost\n                if defending:\n                    # If no hostile majority is present or approaching, don\'t\n                    # invent an immediate threat just to justify a garrison.\n                    if prediction[target] < 0.7:\n                        continue\n                if profit <= 1.0:\n                    continue\n                priority = profit / (needed * (2.0 + 0.65 * arrival_delay))\n                priority += sum(0.03 for _, _, i in group\n                                if tokens[i][2] == target)\n                key = (priority, profit, -target)\n                if best is None or key > best[0]:\n                    best = (key, target, group)\n            if best is None:\n                break\n            _, target, group = best\n            for _, _, index in group:\n                goals[index] = target\n                free.remove(index)\n            candidates.remove(target)\n        return goals\n\n    def act(self, obs):\n        start = time.perf_counter()\n        deadline = start + max(0.0, 0.58 * TIME_BUDGET)\n        n = int(obs.get("n_nodes", 0))\n        if n <= 0:\n            return []\n        if self.map_data is None:\n            self.map_data = preprocess_map(n, obs.get("edges", []))\n        if (not obs.get("action_format_correct_last_turn", True)\n                or obs.get("n_invalid_actions_last_turn", 0) > 0):\n            self.bad_reports += 1\n        if self.bad_reports >= 2:\n            self.conservative = True\n        self._synchronize_tokens(obs)\n        prediction = self._opponent_prediction(obs)\n        goals = self._plan(obs, prediction, deadline)\n        _, lengths, _, hops = self.map_data\n        t = int(obs["turn"])\n        proposals = {}\n        token_moves = []\n        for i, token in enumerate(self.tokens):\n            node, ready, old_goal = token\n            target = goals[i]\n            token[2] = target\n            if ready > t or node == target:\n                continue\n            hop = hops[node][target]\n            if hop < 0:\n                continue\n            proposals[node, hop] = proposals.get((node, hop), 0) + 1\n            token_moves.append((i, node, hop))\n\n        action = legal_action(proposals, obs["player_units"], lengths, n)\n        accepted = {(u, v): count for u, v, count in action}\n        for i, node, hop in token_moves:\n            if accepted.get((node, hop), 0) > 0:\n                accepted[node, hop] -= 1\n                self.tokens[i][0] = hop\n                self.tokens[i][1] = t + lengths[node, hop]\n        self.previous_turn = t\n        return action\n'
