_FALLBACK_SRC = '# Exact action format: list[tuple[int, int, int]], [(from_node, to_node, count), ...].\n# Revenue: sum of node_value[i] over all nodes the player owns.\n# Upkeep: UPKEEP * (UNITS_PER_PLAYER - units on the player\'s own base).\n# Ownership persists without units; capture needs two consecutive strict majorities.\n# Moves precede landing, ownership checks, and payout. There is no shared payout:\n# an opponent capture transfers the entire node\'s revenue.\n\nTIME_BUDGET = 0.25\n\nN_TURNS = 80\nUNITS_PER_PLAYER = 20\nUPKEEP = 2.0\n\n\ndef payout(node_value, owned, units_at_base):\n    """The specification\'s exact per-turn profit formula."""\n    revenue = sum(value for value, owner in zip(node_value, owned) if owner)\n    upkeep = UPKEEP * (UNITS_PER_PLAYER - units_at_base)\n    return float(revenue - upkeep)\n\n\ndef preprocess_map(obs):\n    """Weighted shortest paths, with deterministic first-hop tie breaking."""\n    n = int(obs["n_nodes"])\n    lengths = [[0] * n for _ in range(n)]\n    distance = [[10**6] * n for _ in range(n)]\n    hop = [[-1] * n for _ in range(n)]\n    for u in range(n):\n        distance[u][u] = 0\n    for u, v, length in obs["edges"]:\n        lengths[u][v] = lengths[v][u] = int(length)\n        distance[u][v] = distance[v][u] = int(length)\n        hop[u][v], hop[v][u] = int(v), int(u)\n    for k in range(n):\n        for u in range(n):\n            if u == k:\n                continue\n            for v in range(n):\n                if u == v:\n                    continue\n                candidate = distance[u][k] + distance[k][v]\n                first = hop[u][k]\n                if first >= 0 and (\n                    candidate < distance[u][v]\n                    or (\n                        candidate == distance[u][v]\n                        and (hop[u][v] < 0 or first < hop[u][v])\n                    )\n                ):\n                    distance[u][v] = candidate\n                    hop[u][v] = first\n    return lengths, distance, hop\n\n\ndef make_plan(obs, distance, hop):\n    """One inexpensive capture unit per profitable, uncontested destination.\n\n    Reconstruct all assignments each turn. In-flight units reserve destinations\n    before new base units are deployed, so long edges do not cause repeat sends.\n    Captured nodes need no garrison: surplus units immediately head home.\n    """\n    n = int(obs["n_nodes"])\n    turn = int(obs.get("turn", 0))\n    remaining = max(0, N_TURNS - turn)\n    base = int(obs["player_base"])\n    enemy_base = int(obs["opponent_base"])\n    values = obs["node_value"]\n    owned = obs["player_owned"]\n    enemy = obs["opponent_units"]\n    lead = obs["player_lead_turns"]\n    units = obs["player_units"]\n\n    threatened = [int(enemy[v]) > 0 for v in range(n)]\n    for _, destination, count, _ in obs.get("opponent_transits", []):\n        if count > 0:\n            threatened[destination] = True\n\n    targets = [\n        v for v in range(n)\n        if v != base and v != enemy_base\n        and values[v] > 0 and not owned[v] and not threatened[v]\n    ]\n\n    # Sources are (node, delay, movable, count). Transit sources are reservations,\n    # not movable units; their current edge can never be interrupted.\n    sources = []\n    for source, destination, count, arrival in obs.get("player_transits", []):\n        if count > 0:\n            sources.append((int(destination), max(0, int(arrival) - turn),\n                            False, int(count)))\n    for v in range(n):\n        if units[v] > 0:\n            sources.append((v, 0, True, int(units[v])))\n\n    free = [entry[3] for entry in sources]\n    candidates = []\n    for index, (source, delay, movable, count) in enumerate(sources):\n        for target in targets:\n            travel = delay + distance[source][target]\n            # If already standing on the target with one lead, capture is this\n            # turn. A new arrival must survive one additional turn-end.\n            if travel == 0:\n                capture_offset = 0 if lead[target] > 0 else 1\n            else:\n                capture_offset = travel\n            earning_turns = max(0, remaining - capture_offset)\n\n            # Full round-trip upkeep, including the second capture turn.\n            # For a standing unit, include this turn\'s capture upkeep as well.\n            cost = UPKEEP * (\n                travel + distance[target][base] + (1 if travel == 0 else 0)\n            )\n            benefit = values[target] * earning_turns\n            if benefit <= cost + 4.0:\n                continue\n\n            # Nearest-first, and use already-deployed units before launching\n            # fresh ones when their travel times are the same.\n            candidates.append((\n                travel, int(source == base), -values[target],\n                target, index\n            ))\n    candidates.sort()\n\n    assigned = set()\n    plan = {}\n    for _, _, _, target, index in candidates:\n        if target in assigned or free[index] <= 0:\n            continue\n        source, delay, movable, _ = sources[index]\n        assigned.add(target)\n        free[index] -= 1\n        if movable and source != target:\n            destination = hop[source][target]\n            if destination >= 0:\n                key = (source, destination)\n                plan[key] = plan.get(key, 0) + 1\n\n    # Unassigned on-node units are unnecessary upkeep. Return them along a\n    # fastest path. Assigned units already on their capture node stay there.\n    for index, (source, delay, movable, _) in enumerate(sources):\n        count = free[index]\n        if movable and source != base and count > 0:\n            destination = hop[source][base]\n            if destination >= 0:\n                key = (source, destination)\n                plan[key] = plan.get(key, 0) + count\n\n    return plan\n\n\ndef legal_action(plan, obs, lengths):\n    """Validate every move using only start-of-turn unit availability."""\n    n = int(obs["n_nodes"])\n    available = [int(x) for x in obs["player_units"]]\n    action = []\n    for (source, destination), requested in sorted(plan.items()):\n        source, destination = int(source), int(destination)\n        if not (0 <= source < n and 0 <= destination < n):\n            continue\n        if source == destination or lengths[source][destination] <= 0:\n            continue\n        count = min(max(0, int(requested)), available[source])\n        if count > 0:\n            action.append((int(source), int(destination), int(count)))\n            available[source] -= count\n    return action\n\n\nclass Strategy:\n    def __init__(self, player_id):\n        self.player_id = int(player_id)\n        self.map_key = None\n        self.map_data = None\n\n    def act(self, obs):\n        if not obs or not obs.get("n_nodes"):\n            return []\n        # Only static map data is cached; missed turns need no reconciliation.\n        key = (\n            int(obs["n_nodes"]),\n            tuple(tuple(int(x) for x in edge) for edge in obs.get("edges", [])),\n        )\n        if self.map_data is None or key != self.map_key:\n            self.map_data = preprocess_map(obs)\n            self.map_key = key\n        lengths, distance, hop = self.map_data\n        plan = make_plan(obs, distance, hop)\n        return legal_action(plan, obs, lengths)\n'
